from pathlib import Path
import sys,json,time,numpy as np
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-corrected-coupled-reference'));from setup import m,r,wave
scale=np.zeros(r.N)
for b in r.blocks:scale[b['indices']]=b['step']
fixed=[]
for b in r.blocks:
 b['fixed_zero']=b['original']['domain']!='positive' and ((b['normal_indices'] is None and b['original']['cap']==0) or (b['normal_indices'] is not None and not np.any(b['original']['weights'])))
 if b['fixed_zero']:fixed.extend(b['indices'])
fixed=np.array(fixed,dtype=int);active=np.array([i for i in range(r.N) if i not in set(fixed)])
def interior(y):
 for b in r.blocks:
  z=y[b['indices']];domain=b['original']['domain']
  if b['fixed_zero']:
   if np.any(z!=0):return False
   continue
  if domain=='positive':
   if min(z)<=0:return False
  else:
   radius=r.radius(b,y)
   if radius<=0 or z@z>=radius*radius:return False
 return True
def initialize(seed):
 y=seed.copy()
 for b in r.blocks:
  if b['original']['domain']=='positive':y[b['indices']]=np.maximum(y[b['indices']],1.)
 for b in r.blocks:
  if b['original']['domain']!='positive':
   ii=b['indices'];cap=r.radius(b,y)
   if b['fixed_zero']:y[ii]=0;continue
   assert cap>0;y[ii]*=min(1.,.5*cap/max(np.linalg.norm(y[ii]),1e-300))
 assert interior(y);return y
def barrier(y,mu,jac=False,omit_radius=False):
 F=r.S@y+r.q;D=r.S.copy() if jac else None
 for b in r.blocks:
  ii=b['indices'];z=y[ii];n=len(ii)
  if b['fixed_zero']:
   F[ii]=z
   if jac:D[ii]=r.E[ii]
   continue
  if b['original']['domain']=='positive':
   F[ii]-=mu/z
   if jac:D[np.ix_(ii,ii)]+=np.diag(mu/z**2)
  else:
   cap=r.radius(b,y);slack=cap*cap-z@z;F[ii]+=2*mu*z/slack
   if jac:
    D[np.ix_(ii,ii)]+=2*mu*np.eye(n)/slack+4*mu*np.outer(z,z)/slack**2
    if b['normal_indices'] is not None and not omit_radius:D[np.ix_(ii,b['normal_indices'])]-=4*mu*cap*np.outer(z,b['original']['weights'])/slack**2
 return scale[:,None]*D if jac else scale*F
rng=np.random.default_rng(20261005);errors=[];negative=[]
for i in range(24):
 y=initialize(rng.normal(size=r.N)*.1);direction=rng.normal(size=r.N);direction[fixed]=0;direction/=np.linalg.norm(direction);h=1e-7;mu=10**rng.uniform(-3,0);fd=(barrier(y+h*direction,mu)-barrier(y-h*direction,mu))/(2*h);expected=barrier(y,mu,True)@direction;wrong=barrier(y,mu,True,True)@direction;errors.append(float(max(abs(fd-expected)/(1+abs(expected)))));negative.append(float(max(abs(fd-wrong)/(1+abs(expected)))))
controls=dict(cases=24,maximum_directional_error=max(errors),omitted_radius_error=max(negative));assert max(errors)<=1e-5 and max(negative)>1e-3;(p/'controls.json').write_text(json.dumps(controls,indent=2));print('CONTROLS',json.dumps(controls),flush=True)
results={}
for name,seed in [('cold',np.zeros(r.N)),('capped',m.old[r.remaining])]:
 start=time.monotonic();y=initialize(seed);best=r.recover(y);bestnr=float(max(abs(m.residual(best))/(1+abs(best))));records=[];termination='complete';solves=0
 for exponent in range(13):
  mu=10.**(-exponent);stage_ok=False
  for step in range(156-solves):
   F=barrier(y,mu);maximum=float(max(abs(F)))
   if maximum<=1e-8:stage_ok=True;break
   D=barrier(y,mu,True)
   try:
    delta=np.zeros(r.N);delta[active]=np.linalg.solve(D[np.ix_(active,active)],-F[active])
   except np.linalg.LinAlgError:termination='singular-Jacobian';break
   solves+=1;linear=float(max(abs(D@delta+F)/(1+abs(F))));alpha=1.
   if not interior(y+delta):
    lo=0.;hi=1.
    for _ in range(48):
     mid=(lo+hi)*.5
     if interior(y+mid*delta):lo=mid
     else:hi=mid
    alpha=.99*lo
   merit=float(F@F);accepted=False
   for backtrack in range(8):
    trial=y+alpha*delta
    if interior(trial):
     ft=barrier(trial,mu)
     if ft@ft<=(1-1e-4*alpha)*merit:accepted=True;break
    alpha*=.5
   records.append(dict(mu=mu,step=step,maximum_scaled_barrier_residual=maximum,linear_residual=linear,alpha=alpha,accepted=accepted,backtracks=backtrack))
   if not accepted:termination='line-search-failed';break
   y=trial;full=r.recover(y);nr=float(max(abs(m.residual(full))/(1+abs(full))))
   if nr<bestnr:bestnr=nr;best=full
  if not stage_ok and max(abs(barrier(y,mu)))<=1e-8:stage_ok=True
  print(name,'stage',mu,'ok',stage_ok,'best',bestnr,flush=True)
  if not stage_ok:
   if termination=='complete':termination='global-step-cap'
   break
 x=best;polish=[]
 for i in range(8):
  F=m.residual(x);nr=float(max(abs(F)/(1+abs(x))))
  if nr<=1e-10:break
  D=m.residual(x,True);delta,_,rank,_=np.linalg.lstsq(D,-F,rcond=1e-12);accepted=False
  for k in range(8):
   alpha=2.**-k;trial=x+alpha*delta;ft=m.residual(trial)
   if ft@ft<=(1-1e-4*alpha)*(F@F):accepted=True;break
  polish.append(dict(step=i,rank=int(rank),accepted=accepted,alpha=alpha,initial_natural=nr))
  if not accepted:break
  x=trial
 natural=float(max(abs(m.residual(x))/(1+abs(x))));grad=m.gradient_primal(x);dense=m.H@x+m.g;agreement=float(max(abs(grad-dense)/(1+np.maximum(abs(grad),abs(dense)))));_,sweep=wave(x);feas=[]
 for b in m.blocks:
  z=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(z)))
  elif domain=='box':error=max(0,float(max(abs(z)))-cap)/(1+cap)
  elif domain=='ball':error=max(0,float(np.linalg.norm(z))-cap)/(1+cap)
  feas.append(error)
 passed=natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5;output=dict(status='reference-pass' if passed else 'reference-failed',continuation_termination=termination,newton_solves=solves,seconds=time.monotonic()-start,best_continuation_natural=bestnr,natural=natural,feasibility=max(feas),primal=agreement,wave=sweep,polish=polish,history=records);results[name]=output;np.savez(p/(name+'.npz'),impulses=x,velocities=m.vfree+m.M@m.J.T@x);(p/'result.json').write_text(json.dumps(results,indent=2));print('ARM',name,json.dumps({k:v for k,v in output.items() if k!='history'}),flush=True)
if not all(x['status']=='reference-pass' for x in results.values()):raise SystemExit(1)

